<?php
namespace App\Http\Controllers; use App\Models\{PracticumClass,PracticumRegistration,RequirementSubmission,User}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class StudentController extends Controller {
 public function dashboard(Request $r){ $registrations=PracticumRegistration::with(['preferredClass.course','preferredClass.laboratory','finalClass.course','finalClass.laboratory','submissions.requirement'])->where('student_id',$r->user()->id)->latest()->get(); return view('mahasiswa.dashboard',compact('registrations')); }
 public function practicums(Request $r){ $registered=PracticumRegistration::where('student_id',$r->user()->id)->pluck('practicum_class_id'); $classes=PracticumClass::with(['course.requirements','laboratory','lecturer'])->withCount('registrations')->where('is_active',true)->whereNotIn('id',$registered)->where(fn($q)=>$q->whereNull('enrollment_deadline')->orWhere('enrollment_deadline','>=',now()))->orderBy('practicum_date')->orderBy('start_time')->get(); return view('mahasiswa.practicums',compact('classes')); }
 public function practicumCertificate(Request $r, PracticumRegistration $registration){ abort_unless((int) $registration->student_id===(int) $r->user()->id && $registration->passed(),403); $registration->load(['student','finalClass.course','finalClass.laboratory']); $head=User::where('role','kepala_labor')->where('laboratory_id',$registration->finalClass->laboratory_id)->first(); return view('mahasiswa.practicum-certificate',compact('registration','head')); }
 public function apply(PracticumClass $class){ abort_unless($class->registrationIsOpen(),403,'Batas pengisian praktikum telah lewat.'); $class->load(['course.requirements','laboratory','lecturer']); return view('mahasiswa.apply',compact('class')); }
 public function store(Request $r,PracticumClass $class){ abort_unless($class->registrationIsOpen(),403,'Batas pengisian praktikum telah lewat.'); $requirements=$class->course->requirements()->where('is_required',true)->get(); foreach($requirements as $req){ $r->validate(['req_'.$req->id=>'required|file|mimes:pdf,jpg,jpeg,png|max:2048']); } DB::transaction(function() use($r,$class,$requirements){ $reg=PracticumRegistration::create(['student_id'=>$r->user()->id,'practicum_class_id'=>$class->id,'status'=>'pending_verification']); foreach($requirements as $req){ $path=$r->file('req_'.$req->id)->store('praktikum-syarat','public'); RequirementSubmission::create(['registration_id'=>$reg->id,'requirement_id'=>$req->id,'file_path'=>$path]); } }); return redirect()->route('mahasiswa.dashboard')->with('success','Pendaftaran dikirim. Admin akan memverifikasi syarat dan kelas akhir Anda.'); }
}
